def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]

    row_counts = {}
    col_counts = {}
    for r, c in points:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1

    best_row = max(row_counts, key=row_counts.get)
    best_col = max(col_counts, key=col_counts.get)

    if row_counts[best_row] >= col_counts[best_col]:
        axis = best_row
        on_axis = [c for r, c in points if r == axis]
        for c in range(min(on_axis), max(on_axis) + 1):
            if out[axis][c] == 0:
                out[axis][c] = 3
        for r, c in points:
            for rr in range(min(r, axis), max(r, axis) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        axis = best_col
        on_axis = [r for r, c in points if c == axis]
        for r in range(min(on_axis), max(on_axis) + 1):
            if out[r][axis] == 0:
                out[r][axis] = 3
        for r, c in points:
            for cc in range(min(c, axis), max(c, axis) + 1):
                if out[r][cc] == 0:
                    out[r][cc] = 3

    return out
